require __DIR__.'/../app/bootstrap.php';$result=null;$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf();if(time()-($_SESSION['last_lookup']??0)<3)$error='Please wait a moment before checking again.';else{$_SESSION['last_lookup']=time();$result=run('SELECT reference,event_type,date,start,end,status,total,(SELECT COALESCE(SUM(amount),0) FROM payments WHERE reservation_id=r.id) AS paid FROM reservations r WHERE reference=? AND lower(email)=?',[strtoupper(scalar_post('reference')),strtolower(scalar_post('email'))])->fetch();if(!$result)$error='No matching reservation. Check your reference and the email used to book.';}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Track your occasion · Uncorked</title><link rel="stylesheet" href="assets/style.css"></head><body><header><a class="brand" href="index.php">uncorked<span>EVENT STUDIO BAR</span></a><a href="index.php#reserve">Plan an event ↗</a></header><main class="section" style="max-width:850px;margin:auto"><p class="eyebrow">YOUR OCCASION, AT A GLANCE</p><h1 style="font-size:55px">Good times<br><em>in the making.</em></h1><form method="post"><input type="hidden" name="csrf" value="<?= esc($_SESSION['csrf']) ?>"><div class="form-grid"><label>Reservation reference<input name="reference" required placeholder="UNC-XXXXXXXX" value="<?= esc(is_string($_POST['reference']??null)?$_POST['reference']:'') ?>"></label><label>Booking email<input type="email" name="email" required autocomplete="email"></label></div><button class="button">Check reservation ↗</button><?php if($error): ?><p class="error" role="alert"><?= esc($error) ?></p><?php endif; ?></form><?php if($result): ?><section style="padding:30px;border:1px solid var(--line);margin-top:25px"><p class="eyebrow"><?= esc($result['reference']) ?></p><h2><?= esc($result['status']) ?></h2><p><?= esc($result['event_type']) ?> · <?= esc($result['date']) ?><br><?= esc($result['start'].' – '.$result['end']) ?> (Asia/Manila)</p><p>Event total: <?= money($result['total']) ?><br>Recorded payments: <?= money($result['paid']) ?><br>Balance: <?= money($result['total']-$result['paid']) ?></p><p class="help">Pending requests require staff confirmation. Contact the team to request changes.</p></section><?php endif; ?></main></body></html>
